import {createRun,step,distance,energyDrift,stellarFlux,equilibriumTemperature,specificAngularMomentum,LUMINOSITY,SOLAR_TEMPERATURE,AU,DAY} from './sim.js';
const el=id=>document.getElementById(id);
const canvas=el('scene'), ctx=canvas.getContext('2d');
const ui={play:el('play'),step:el('step'),reset:el('reset'),speed:el('speed'),radius:el('radius'),velocity:el('velocity'),radiusValue:el('radius-value'),velocityValue:el('velocity-value'),time:el('time'),distance:el('distance'),flux:el('flux'),drift:el('drift'),runningLabel:el('running-label'),panel:el('inspect-panel'),planetTab:el('planet-tab'),starTab:el('star-tab')};
let run=createRun(), running=true, inspected='planet', trail=[[run.x/AU,run.y/AU]], maxExtent=1.25, accumulator=0, lastFrame=null, message='';
const stars=Array.from({length:130},(_,i)=>{const fract=x=>x-Math.floor(x);return [fract(Math.sin(i*127.1+16)*43758.5453),fract(Math.sin(i*311.7+41)*24163.746),0.35+fract(Math.sin(i*77.2+9)*8731.45)*0.65]});
function startRun(){
  run=createRun(Number(ui.radius.value),Number(ui.velocity.value)/100); trail=[[run.x/AU,run.y/AU]];maxExtent=Math.max(1.25,Number(ui.radius.value)*1.3);accumulator=0;lastFrame=null;message='';
  ui.radiusValue.textContent=`${Number(ui.radius.value).toFixed(2)} AU`;ui.velocityValue.textContent=`${ui.velocity.value}%`;update();draw();
}
function setPlaying(value){running=value;accumulator=0;lastFrame=null;ui.play.innerHTML=running?'❚❚ <span>Pause</span>':'▶ <span>Play</span>';ui.play.setAttribute('aria-label',running?'Pause simulation':'Play simulation');ui.runningLabel.textContent=running?'RUNNING':'PAUSED'}
function advance(){try{step(run);trail.push([run.x/AU,run.y/AU]);if(trail.length>1800)trail.shift();maxExtent=Math.max(maxExtent,Math.abs(run.x/AU)*1.15,Math.abs(run.y/AU)*1.15)}catch(err){message=err.message;setPlaying(false)}}
function update(){const r=distance(run), drift=energyDrift(run), flux=stellarFlux(r);ui.time.innerHTML=`${(run.stepCount*run.initial.stepSeconds/DAY).toLocaleString(undefined,{maximumFractionDigits:0})} <small>days</small>`;ui.distance.innerHTML=`${(r/AU).toFixed(3)} <small>AU</small>`;ui.flux.innerHTML=`${Math.round(flux).toLocaleString()} <small>W/m²</small>`;ui.drift.textContent=drift.toExponential(2);if(inspected==='planet'){ui.panel.innerHTML=`<dl><div><dt>Speed</dt><dd>${(Math.hypot(run.vx,run.vy)/1000).toFixed(2)} km/s</dd></div><div><dt>Equilibrium temp.</dt><dd>${equilibriumTemperature(flux).toFixed(0)} K</dd></div><div><dt>Angular momentum</dt><dd>${specificAngularMomentum(run).toExponential(2)} m²/s</dd></div></dl><p class="inspect-note">Temperature: blackbody, albedo 0.30; no atmosphere.${message?' Run halted: '+message:''}</p>`}else{ui.panel.innerHTML=`<dl><div><dt>Effective temperature</dt><dd>${SOLAR_TEMPERATURE.toLocaleString()} K</dd></div><div><dt>Luminosity</dt><dd>${LUMINOSITY.toExponential(2)} W</dd></div><div><dt>Model</dt><dd>Fixed Sun-like star</dd></div></dl><p class="inspect-note">Blackbody luminosity is an approximation.</p>`}}
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);
  let bg=ctx.createRadialGradient(w*.5,h*.53,5,w*.5,h*.53,Math.max(w,h)*.75);bg.addColorStop(0,'#1b3430');bg.addColorStop(.42,'#102323');bg.addColorStop(1,'#0a161a');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
  for(const [x,y,a] of stars){ctx.fillStyle=`rgba(203,224,205,${a*.35})`;ctx.beginPath();ctx.arc(x*w,y*h,a>.85?1.1:.55,0,Math.PI*2);ctx.fill()}
  const centerX=w*.50,centerY=h*.55,scale=Math.min(w*.36/maxExtent,h*.68/(maxExtent*.48));const project=(x,y)=>[centerX+x*scale,centerY-y*scale*.45];
  ctx.save();ctx.strokeStyle='rgba(155,189,167,.07)';ctx.lineWidth=1;
  for(let p=-3;p<=3;p++){const [x1,y1]=project(-3,p),[x2,y2]=project(3,p);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();const [x3,y3]=project(p,-3),[x4,y4]=project(p,3);ctx.beginPath();ctx.moveTo(x3,y3);ctx.lineTo(x4,y4);ctx.stroke()}
  const radius=run.initial.distanceAU;ctx.setLineDash([3,6]);ctx.strokeStyle='rgba(191,216,185,.34)';ctx.beginPath();for(let i=0;i<=160;i++){const theta=i*2*Math.PI/160,[x,y]=project(radius*Math.cos(theta),radius*Math.sin(theta));if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();ctx.setLineDash([]);
  if(trail.length>1){ctx.beginPath();trail.forEach(([x,y],i)=>{const p=project(x,y);if(!i)ctx.moveTo(...p);else ctx.lineTo(...p)});ctx.strokeStyle='rgba(224,231,178,.84)';ctx.lineWidth=1.3;ctx.stroke()}
  ctx.restore();
  const halo=ctx.createRadialGradient(centerX,centerY,2,centerX,centerY,85);halo.addColorStop(0,'rgba(255,222,161,.8)');halo.addColorStop(.13,'rgba(247,195,121,.25)');halo.addColorStop(.5,'rgba(229,178,109,.07)');halo.addColorStop(1,'rgba(229,178,109,0)');ctx.fillStyle=halo;ctx.beginPath();ctx.arc(centerX,centerY,85,0,Math.PI*2);ctx.fill();
  const sun=ctx.createRadialGradient(centerX-5,centerY-5,1,centerX,centerY,17);sun.addColorStop(0,'#fff7d2');sun.addColorStop(.55,'#ffd790');sun.addColorStop(1,'#de9564');ctx.fillStyle=sun;ctx.beginPath();ctx.arc(centerX,centerY,16,0,2*Math.PI);ctx.fill();
  const [px,py]=project(run.x/AU,run.y/AU);const ph=ctx.createRadialGradient(px,py,5,px,py,28);ph.addColorStop(0,'rgba(126,204,220,.30)');ph.addColorStop(1,'rgba(102,177,190,0)');ctx.fillStyle=ph;ctx.beginPath();ctx.arc(px,py,28,0,Math.PI*2);ctx.fill();
  ctx.save();ctx.beginPath();ctx.arc(px,py,11,0,2*Math.PI);ctx.clip();let globe=ctx.createRadialGradient(px-5,py-5,1,px+3,py+3,19);globe.addColorStop(0,'#b0ddd5');globe.addColorStop(.32,'#4c9da3');globe.addColorStop(.7,'#185765');globe.addColorStop(1,'#102e39');ctx.fillStyle=globe;ctx.fillRect(px-12,py-12,24,24);ctx.strokeStyle='rgba(226,238,222,.52)';ctx.lineWidth=2;for(let i=-1;i<3;i++){ctx.beginPath();ctx.ellipse(px-2,py+i*5,13,3,-.25,0,Math.PI*1.35);ctx.stroke()}ctx.restore();ctx.strokeStyle='rgba(172,225,221,.7)';ctx.lineWidth=.8;ctx.beginPath();ctx.arc(px,py,11,0,2*Math.PI);ctx.stroke();
  ctx.font='600 9px system-ui, sans-serif';ctx.fillStyle='rgba(220,234,220,.8)';ctx.fillText('STAR',centerX+25,centerY-10);ctx.fillText('PLANET',Math.min(px+16,w-55),Math.max(py-14,48));
}
function frame(now){if(lastFrame===null)lastFrame=now;let elapsed=Math.min((now-lastFrame)/1000,.25);lastFrame=now;if(running){accumulator+=elapsed*Number(ui.speed.value);let count=0;while(accumulator>=1&&count<30&&running){advance();accumulator-=1;count++}update();draw()}requestAnimationFrame(frame)}
ui.play.addEventListener('click',()=>setPlaying(!running));ui.step.addEventListener('click',()=>{setPlaying(false);advance();update();draw()});ui.reset.addEventListener('click',startRun);for(const slider of [ui.radius,ui.velocity])slider.addEventListener('input',startRun);
for(const [button,name] of [[ui.planetTab,'planet'],[ui.starTab,'star']])button.addEventListener('click',()=>{inspected=name;for(const b of [ui.planetTab,ui.starTab]){const selected=b===button;b.classList.toggle('selected',selected);b.setAttribute('aria-selected',String(selected))}update()});
el('export').addEventListener('click',async()=>{const {exportRun}=await import('./sim.js');const blob=new Blob([JSON.stringify(exportRun(run),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='sim-orbit-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
window.addEventListener('resize',resize);window.addEventListener('visibilitychange',()=>{lastFrame=null});resize();update();requestAnimationFrame(frame);
